#!/bin/bash
set -euo pipefail

# Checks that every subcomponent the VEX document lists for an image occurs in
# at least one of the given releases of that image. This catches a wrong
# package name or version in a statement, also for statements whose
# vulnerability no scanner reports yet.
#
# The packages of a release are taken from an SBOM generated by Trivy, with
# the qualifiers of their PURLs removed, like the subcomponents have none.
#
# Usage: check-vex-subcomponents.sh <image-name> <vex-document> <release>...
#
# A release is a tag with digest like 1.13.0@sha256:...

name="$1"
document="$2"
shift 2

subcomponents="$(jq -r --arg prefix "pkg:oci/$name?" \
  '[.statements[].products[] | select(."@id" | startswith($prefix)) | .subcomponents[]?."@id"] | unique[]' \
  "$document")"

if [ -z "$subcomponents" ]; then
  echo "✅ the VEX document lists no subcomponents for $name"
  exit 0
fi

packages=""
for release in "$@"; do
  sbom="$(mktemp)"
  trivy image --quiet --format cyclonedx --output "$sbom" "samply/$name:$release"
  packages+="$(jq -r '.. | objects | .purl? // empty' "$sbom" | sed 's/?.*//')"$'\n'
done

missing=0
while read -r subcomponent; do
  if grep -qxF "$subcomponent" <<< "$packages"; then
    echo "✅ $subcomponent occurs in a release of $name"
  else
    echo "🆘 $subcomponent occurs in no release of $name"
    missing=1
  fi
done <<< "$subcomponents"

exit "$missing"
